-- Demo seed for MARKETING module (promo + ad + news).
-- ONLY touches T_* tables (never CP_*). Owner = USR-ORGANIZER, buyer = USR-AUDIENCE.
-- Requires: migrate4 (accounts) + migrate5/6/9/12/14 (T_* tables + columns).
-- Idempotent (IF NOT EXISTS per CODE). Run:
--   sqlcmd -S <host>,<port> -U <user> -P <pass> -d <DB_NAME> -C -b -i scripts/seed-marketing.sql
-- Or: task seed-marketing
SET XACT_ABORT ON;
BEGIN TRAN;

-- 6 promos: aktif / akan_datang / kedaluwarsa / kuota_habis / nonaktif / used --
IF NOT EXISTS (SELECT 1 FROM dbo.T_PROMO WHERE CODE = 'PRM-MKT01')
  INSERT INTO dbo.T_PROMO (CODE, PROMO_CODE, DESCRIPTION, DISCOUNT_PERCENT, MAX_DISCOUNT_AMOUNT, MIN_PURCHASE, MAX_USES, USED_COUNT, MAX_PER_USER, VALID_FROM, VALID_TO, STATUS, SCOPE_TYPE, ORGANIZER_CODE)
  VALUES ('PRM-MKT01', 'MKT-AKTIF10', 'Diskon 10% aktif, maks Rp30 rb, min 50 rb', 10.00, 30000, 50000, 100, 5, 2, DATEADD(day, -5, GETDATE()), DATEADD(day, 20, GETDATE()), 'ACTIVE', 'ALL', 'USR-ORGANIZER');
IF NOT EXISTS (SELECT 1 FROM dbo.T_PROMO WHERE CODE = 'PRM-MKT02')
