IF NOT EXISTS (SELECT 1 FROM dbo.T_PROMO_SCOPE WHERE PROMO_CODE = 'PRM-MKT06')
  INSERT INTO dbo.T_PROMO_SCOPE (CODE, PROMO_CODE, SCOPE_TYPE, EVENT_CODE)
  SELECT 'PSC-MKT06', 'PRM-MKT06', 'EVENT', CODE FROM dbo.T_EVENT WHERE ORGANIZER_CODE = 'USR-ORGANIZER' AND IS_DELETED = 0 ORDER BY CODE OFFSET 0 ROWS FETCH NEXT 1 ROWS ONLY;

-- Usage history for MKT-USED10 (3 orders) --
IF NOT EXISTS (SELECT 1 FROM dbo.T_PROMO_USAGE WHERE CODE = 'PU-MKT01')
  INSERT INTO dbo.T_PROMO_USAGE (CODE, PROMO_CODE, ORDER_CODE, USER_CODE, DISCOUNT_AMOUNT, USED_AT)
  SELECT 'PU-MKT01', 'PRM-MKT06', CODE, 'USR-AUDIENCE', 25000, DATEADD(day, -2, GETDATE()) FROM dbo.T_ORDER WHERE STATUS = 'PAID' ORDER BY ORDER_DATE DESC OFFSET 0 ROWS FETCH NEXT 1 ROWS ONLY;
